         .json({ erro: 'NAO_ENCONTRADO', mensagem: 'Encontro não encontrado.' })
     }
     if (typeof req.body?.codigo !== 'string') {
       return res
         .status(422)
         .json({ erro: dadosInvalidos, mensagem: 'Código é obrigatório e deve ser texto.' })
